-- ----------------------------
-- Table structure for message
-- ----------------------------
DROP TABLE IF EXISTS `message`;
CREATE TABLE `message` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '消息表的自增主键ID',
  `content` varchar(255) COLLATE utf8mb4_bin DEFAULT NULL COMMENT '消息内容（消息体）',
  `message_type` int(2) DEFAULT NULL COMMENT '消息类型（指标数据、互动、系统消息...）',
  `receiver_id` int(11) DEFAULT NULL COMMENT '接收者ID',
  `sender_id` int(11) DEFAULT NULL COMMENT '发送者ID',
  `is_read` tinyint(1) DEFAULT NULL COMMENT '消息是否已经阅读',
  `content_id` int(11) DEFAULT NULL COMMENT '关联的内容ID',
  `create_time` datetime DEFAULT NULL COMMENT '消息的发送时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin ROW_FORMAT=DYNAMIC;

