-- ----------------------------
-- Table structure for news
-- ----------------------------
DROP TABLE IF EXISTS `news`;
CREATE TABLE `news` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(255) DEFAULT NULL,
  `content` longtext,
  `tag_id` int(11) DEFAULT NULL,
  `cover` varchar(500) DEFAULT NULL,
  `reader_ids` text,
  `is_top` tinyint(1) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of news
-- ----------------------------
INSERT INTO `news` VALUES ('1', 'Donna Karan 2026 春夏时装秀', '<p>Donna Karan: Brand Introduction</p><p>Donna Karanis a seminal American luxury fashion house renowned for its timeless, sensual, and sophisticated designs that cater to the modern urban woman. Founded in 1984 by designerDonna Karan, the brand revolutionized womens wear with its philosophy of effortless elegance and versatile dressing.</p><p>Core Philosophy & Signature Style<br>The brands foundational concept is the \"Seven Easy Pieces\" system. This idea proposed that a womans wardrobe could be built around seven interchangeable, high-quality essentials (e.g., a bodysuit, tailored pants, a skirt, a jacket, a dress, and leather goods) that could be mixed and matched to create countless outfits for any occasion, from day to night.<br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016315212.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016315212.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016312603.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016312603.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016312714.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016312714.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016316975.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016316975.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/20250919101631126.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/20250919101631126.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016316847.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016316847.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016317338.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016317338.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016316389.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016316389.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016314010.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016314010.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163137211.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163137211.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163177612.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163177612.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163171113.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163171113.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163133614.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163133614.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163186515.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163186515.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163178416.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250919/2025091910163178416.jpg\" style=\"\"/><br><img src=\"https://img1.cfw.cn/editors/attached/image/20250919/202509191016325017.jpg\" alt=\"\" data-href=\"https://img1.cfw.cn/editors/attached/image/20250