-- ----------------------------
-- Table structure for user
-- ----------------------------
DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT COMMENT '用户编号',
  `user_account` varchar(50) DEFAULT NULL COMMENT '用户账号',
  `user_name` varchar(50) DEFAULT NULL COMMENT '用户昵称',
  `user_pwd` varchar(100) DEFAULT NULL COMMENT '用户密码',
  `user_avatar` varchar(255) DEFAULT NULL COMMENT '用户头像',
  `user_email` varchar(50) DEFAULT NULL COMMENT '用户邮箱',
  `user_role` int(11) DEFAULT NULL COMMENT '用户角色',
  `is_login` tinyint(1) DEFAULT NULL COMMENT '可登录状态(0：可用，1：不可用)',
  `is_word` tinyint(1) DEFAULT NULL COMMENT '禁言状态(0：可用，1：不可用)',
  `create_time` datetime DEFAULT NULL COMMENT '用户注册时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=34 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;

